          k(r(tr + 0.25), toon={**PHANDS(n, p), 'bend': BENT(0.0, s=0.3, n=0.15), 'face': {**PF[n], 'eye': 0.3, 'brow': 0.8}}, toonDur=0.12),
          # then they lean back in and read it, the heads sweeping once
