# 4c: « Toute la rue s'est grattée. » All four spring up and scratch at once: her back against a lamp post (rubbing up and down), a baguette down his
#     back, both hands in her hair, a foot rubbing his calf while his hands scratch his belly
D4c = st.dur('S04c')
LAMP4 = [5.45, 0.0, -3.35]
F4c = [8.9, 1.6, 3.6]; L4c = [6.061, 1.054, -5.973]
C4c = cam(0.0, F4c, add(F4c, [-0.05, 0.0, -0.12]), L4c, L4c, lens=43, ease='inOut')
P4c = dict(P4); P4c['p1'] = add(LAMP4, [0.25, 0.0, 0.18])
chkc('S04c', C4c, {**{f'{n}top': add(p, [0, 2.35, 0]) for n, p in P4c.items()}, **{f'{n}feet': p for n, p in P4c.items()}, 'lampTop': add(LAMP4, [0, 3.6, 0])})
SPRING4 = 0.04; SC0 = 0.16
def scr(t0, t1, fn, step=0.067):
    out, t_, i = [], t0, 0
    while t_ < t1 - 0.02: out.append(fn(r(t_), i)); t_ += step; i += 1
    return out
RELIEF = {'p1': {'lid': 0.85, 'mouth': 'O', 'brow': 0.7}, 'p2': {'lid': 0.7, 'mouth': 'zigzag', 'brow': -0.4}, 'p3': {'lid': 0.0, 'eye': 0.4, 'mouth': 'clench', 'brow': 0.9}, 'p4': {'lid': 0.9, 'mouth': 'tongueout', 'brow': 0.5}}
act4c, props4c = [], []
for n, p in P4c.items():
    ry = r(yaw(p, F4c) * 0.9); f = RELIEF[n]
    ks = [k(-0.5, look='camera'), k(0.0, toon={**PHANDS(n, P4[n]), 'bend': BENT(0.0, s=0.4, n=0.3), 'face': PF[n]}, toonDur=0.0),
          k(SPRING4, toon={**HAND(off(p, ry, 0.1, 0.3, 1.2), off(p, ry, 0.1, -0.3, 1.2), 'spread', 'spread'), 'sq': [0.88, 1.14, 0.88], 'hairUp': 1.0, 'face': {**f, 'lid': 0.0, 'eye': 0.4}}, toonDur=0.04, toonEase='out')]
    if n == 'p1':   # her back against the lamp post: she rubs up and down, hands on her hips
        hk = HAND(off(p, ry, 0.0, 0.22, 1.0), off(p, ry, 0.0, -0.22, 1.0), 'open', 'open')
        ks += scr(SC0, D4c, lambda t, i: k(t, toon={**hk, 'sq': [1.03, 0.95, 1.03] if i % 2 else [0.98, 1.04, 0.98], 'lay': [-0.08, 0.04 * (1 - 2 * (i % 2))], 'face': f}, toonDur=0.05), step=0.08)
    elif n == 'p2':  # a baguette down his back over his right shoulder, pumped up and down
        bq0 = off(p, ry, -0.18, 0.12, 1.55)
        hk = lambda i: HAND(add(off(p, ry, 0.02, 0.24, 1.98), [0, 0.07 * (i % 2), 0]), off(p, ry, 0.1, -0.25, 1.0), 'grip', 'rest')
        ks += scr(SC0, D4c, lambda t, i: k(t, toon={**hk(i), 'sq': [1.01, 0.99, 1.01] if i % 2 else [0.99, 1.01, 0.99], 'bend': {'neck': [0.0, 0.1 * (1 - 2 * (i % 2)), 0, 1, None]}, 'face': f}, toonDur=0.05))
        props4c.append(P('baguette4c', 'baguette', pos=bq0, ry=r(ry + 90), rot=[0.0, 0.0, -1.2], scale=1.3,
                         keys=[k(0.0, visible=True), *[k(r(SC0 + 0.067 * j), to=add(bq0, [0, 0.07 * (j % 2), 0]), dur=0.05) for j in range(int((D4c - SC0) / 0.067))]]))
    elif n == 'p3':  # both hands in her hair, frantic
        ks += scr(SC0, D4c, lambda t, i: k(t, toon={'touch': {'R': ['face', -0.3, 1.0 - 0.12 * (i % 2), 0.0, 1, 0.08], 'L': ['face', 0.3, 0.88 + 0.12 * (i % 2), 0.0, 1, 0.08]}, 'hands': {'R': 'claw', 'L': 'claw'}, 'hip': 0,
                                                      'hairUp': 0.5 + 0.4 * (i % 2), 'sq': [1.02, 0.98, 1.02] if i % 2 else [0.98, 1.02, 0.98], 'face': f}, toonDur=0.05))
    else:            # a foot rubbing his calf, both hands on his belly
        ks += scr(SC0, D4c, lambda t, i: k(t, toon={**HAND(off(p, ry, 0.28, 0.12 - 0.08 * (i % 2), 1.18), off(p, ry, 0.28, -0.12 + 0.08 * (i % 2), 1.12), 'claw', 'claw'),
                                                      'plant': {'R': [*off(p, ry, 0.05, -0.05, 0.32 + 0.12 * (i % 2)), 1]}, 'sq': [1.0, 1.0, 1.0], 'face': f}, toonDur=0.05))
    act4c.append(act(n, P4[n] if n != 'p1' else p, ry, 'stand', 'neutral', keys=ks))
st.shot('S04c', 'parisStreet', setOpts={**SSET, 'clear': [-12, 8], 'clearL': [-12, 8]}, actors=act4c,
        props=[FLOORPAPER('papier4c', PAPER4, 4.2, 3.0, ry=8), P('reverbere4c', 'streetLamp', pos=LAMP4, ry=180, opts={'height': 3.8}), *props4c], cams=[C4c])
