    act7b.append(act(n, START, ry, 'stand', 'neutral', keys=ks))
    arms7b.append(P(f'baguettes7b_{i}', 'noArmful', pos=ch(START), ry=ry, keys=[k(0.0, visible=False), k(t0, visible=True), k(t0, to=ch(q), dur=dur, ease='out')]))
